#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════════════════════
#  install-portgpu.sh — moteur TTS NeuTTS résident pour « portgpu » (10.1.33.71)
#  Version 1.0 — à exécuter PERSONNELLEMENT sur 10.1.33.71, en root :
#      sudo bash install-portgpu.sh
#
#  Ce que fait le script :
#    1.  contrôles préalables (Debian/Ubuntu, x86_64, systemd, Python 3.10-3.13,
#        RAM/disque/port libres)
#    2.  paquets système (python3-venv, curl, ca-certificates)
#    3.  utilisateur système « neutts » + arborescence /opt/neutts et /var/lib/neutts
#    4.  fichiers embarqués (serve.py, client.py, voix de référence juliette)
#        avec vérification SHA256
#    5.  jeton Hugging Face (saisie masquée, jamais affiché, validé via l'API)
#    6.  environnement Python (venv + torch CPU + llama-cpp-python + neutts)
#    7.  unité systemd « neutts » (démarrage auto, redémarrage auto, permanent)
#    8.  règle de pare-feu limitée au LAN (jamais 0.0.0.0/0)
#    9.  recette : chargement du modèle, 2 synthèses mesurées, WAV vérifié
#
#  Contrat de variables (toutes surchargeables à l'exécution) :
#    PORT=8130              port d'écoute
#    BIND=0.0.0.0           adresse d'écoute (127.0.0.1 = local seulement)
#    ALLOW_CIDR=192.168.77.0/24   source autorisée par le pare-feu (jamais /0)
#    LLAMA_VARIANT=cpu      cpu | cu124 | cu126 … (variante du moteur llama.cpp)
#    HF_TOKEN=hf_xxx        jeton Hugging Face (sinon saisie masquée)
#    TOKEN=xxxxxxxx         jeton d'accès du service (sinon généré et affiché)
#    IDLE=0                 inactivité avant arrêt en secondes (0 = jamais)
#    PREFIX=/opt/neutts     code et venv      |  STATE=/var/lib/neutts  données
#    DEPS_FORCE=1           réinstalle l'environnement Python même s'il existe
#    SELFTEST=1             vérifie seulement les fichiers embarqués puis sort
#    PREFIX=… SELFTEST=1 bash install-portgpu.sh   ← test à blanc, sans root
#    PURGE : bash install-portgpu.sh --purge       désinstallation complète
#
#  Après installation, côté client (LXC Hermes 192.168.77.236), deux variables :
#    NEUTTS_URL=http://10.1.33.71:8130
#    NEUTTS_TOKEN=<celui affiché en fin d'installation>
# ═══════════════════════════════════════════════════════════════════════════════
set -Eeuo pipefail
umask 022

VERSION="1.0"
PREFIX="${PREFIX:-/opt/neutts}"
STATE="${STATE:-/var/lib/neutts}"
ENVFILE="${ENVFILE:-/etc/neutts.env}"
UNIT="${UNIT:-/etc/systemd/system/neutts.service}"
SVC_USER="${SVC_USER:-neutts}"
BIND="${BIND:-0.0.0.0}"
PORT="${PORT:-8130}"
IDLE="${IDLE:-0}"
ALLOW_CIDR="${ALLOW_CIDR:-192.168.77.0/24}"
LLAMA_VARIANT="${LLAMA_VARIANT:-cpu}"
MODEL_REPO="${MODEL_REPO:-neuphonic/neutts-nano-french-q4-gguf}"
CODEC_REPO="${CODEC_REPO:-neuphonic/neucodec}"
REPOS="$MODEL_REPO $CODEC_REPO facebook/w2v-bert-2.0"
SELFTEST="${SELFTEST:-0}"
DEPS_FORCE="${DEPS_FORCE:-0}"
THREADS="${THREADS:-$( { nproc 2>/dev/null || echo 4; } | head -1 )}"
if [ "$THREADS" -gt 8 ]; then THREADS=8; fi

SERVE_SHA=8ba6c0c20e56349b5f367f4701a83a718c4e0a7661b5d6b3db010345980b431f
CLIENT_SHA=3fbdfd485d846f5e00a84f5b7cf998304136ad00bbc417a60d40ca95a2bac4ff
TXT_SHA=93476fd69d2a146a0e5103ca7d324cd0cee426f9cdb08e0dc9d69aee4823a51f
WAV_SHA=22255eeb3fc4d49df09952ce59fde7d7b7de17ff117abcdb206f9bc276e64cde

C_OK='\033[32m'; C_KO='\033[31m'; C_HD='\033[1;36m'; C_WR='\033[33m'; C_0='\033[0m'
step() { printf "\n${C_HD}── %s${C_0}\n" "$*"; }
ok()   { printf "   ${C_OK}✓${C_0} %s\n" "$*"; }
warn() { printf "   ${C_WR}!${C_0} %s\n" "$*" >&2; }
die()  { printf "\n${C_KO}ERREUR :${C_0} %s\n" "$*" >&2; exit 1; }
have() { command -v "$1" >/dev/null 2>&1; }

TMP="$(mktemp -d)"; HDR="$TMP/hdr"; BODY="$TMP/body.json"
cleanup() { rm -rf "$TMP"; }
trap cleanup EXIT

printf "${C_HD}install-portgpu.sh v%s${C_0} — moteur TTS NeuTTS résident\n" "$VERSION"

# ── Mode désinstallation ─────────────────────────────────────────────────────
if [ "${1:-}" = "--purge" ]; then
  [ "$(id -u)" -eq 0 ] || die "sudo bash $0 --purge"
  printf "Désinstallation du moteur TTS neutts :\n  service : $UNIT\n  code    : $PREFIX\n  données : $STATE (modèles ~3,5 Go)\n  secrets : $ENVFILE\n"
  read -r -p "tape PURGE pour confirmer : " a
  [ "$a" = "PURGE" ] || die "abandon"
  systemctl disable --now neutts 2>/dev/null || true
  rm -f "$UNIT"; systemctl daemon-reload
  rm -rf "$PREFIX" "$STATE" "$ENVFILE"
  if id -u "$SVC_USER" >/dev/null 2>&1 && [ -z "$(find / -xdev -user "$SVC_USER" -print -quit 2>/dev/null)" ]; then
    userdel "$SVC_USER" || true
  fi
  ok "désinstallation terminée"
  exit 0
fi

# ── 0. Mode test à blanc (fichiers embarqués) ────────────────────────────────
if [ "$SELFTEST" != "0" ]; then
  step "SELFTEST : écriture et vérification des fichiers embarqués dans $PREFIX"
  mkdir -p "$PREFIX/refs"
  cat > "$PREFIX/serve.py" <<'EOF_SERVE'
#!/usr/bin/env python3
"""Serveur TTS NeuTTS résident — local (127.0.0.1) ou distant (LAN).

Endpoints (JSON) :
  GET  /health        -> {"ok", "model", "loaded", "uptime_s", "idle_s", "in_flight", "out_dir"}
  POST /say           <- {"text": "...", "out": "/chemin/local.wav"?, "voice": "juliette"?}
                      -> {"ok": true, "name": "say_....wav", "seconds": 2.4, "bytes": 123456,
                          "chars": 42, "path": "/var/lib/neutts/out/say_....wav"}
  GET  /audio/<name>  -> le WAV correspondant (nom simple uniquement, pas de chemin)
  POST /release       -> arrêt propre immédiat (utilisé par release_command)

Un appelant distant ne peut pas nommer un chemin de sortie : /say sans "out" (ou avec un
chemin hors de NEUTTS_OUT_DIR) écrit dans NEUTTS_OUT_DIR et renvoie "name" ; le WAV se
récupère ensuite par GET /audio/<name>. Un appelant local garde l'ancien comportement
("out" absolu respecté), ce qui reste compatible avec les scripts existants.

Variables d'environnement :
  NEUTTS_HOST          adresse d'écoute (défaut 127.0.0.1 ; 0.0.0.0 = accessible LAN)
  NEUTTS_PORT          port d'écoute (défaut 8130)
  NEUTTS_IDLE_TIMEOUT  secondes d'inactivité avant sortie (défaut 300) ; 0 = jamais
  NEUTTS_MODEL         dépôt backbone (défaut neuphonic/neutts-nano-french-q4-gguf)
  NEUTTS_CODEC         dépôt codec (défaut neuphonic/neucodec)
  NEUTTS_VOICE         voix par défaut (défaut juliette)
  NEUTTS_REFS          dossier des références de voix (défaut <ce dossier>/refs)
  NEUTTS_LOG           journal (défaut <ce dossier>/serve.log)
  NEUTTS_OUT_DIR       dossier de sortie (défaut <ce dossier>/out)
  NEUTTS_TOKEN         si défini, exige l'en-tête X-Neutts-Token (sauf /health)
"""
import json
import os
import re
import struct
import sys
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

HERE = Path(__file__).resolve().parent

HOST = os.environ.get("NEUTTS_HOST", "127.0.0.1")
PORT = int(os.environ.get("NEUTTS_PORT", "8130"))
IDLE_TIMEOUT = float(os.environ.get("NEUTTS_IDLE_TIMEOUT", "300"))
DEFAULT_MODEL = os.environ.get("NEUTTS_MODEL", "neuphonic/neutts-nano-french-q4-gguf")
DEFAULT_CODEC = os.environ.get("NEUTTS_CODEC", "neuphonic/neucodec")
DEFAULT_VOICE = os.environ.get("NEUTTS_VOICE", "juliette")
REFS = Path(os.environ.get("NEUTTS_REFS", str(HERE / "refs")))
LOG = Path(os.environ.get("NEUTTS_LOG", str(HERE / "serve.log")))
OUT_DIR = Path(os.environ.get("NEUTTS_OUT_DIR", str(HERE / "out")))
TOKEN = os.environ.get("NEUTTS_TOKEN", "")
OUT_KEEP_S = float(os.environ.get("NEUTTS_OUT_KEEP_S", "86400"))  # purge des WAV de sortie

NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,80}\.wav$")

_lock = threading.Lock()          # sérialise l'inférence (modèle non réentrant)
_state_lock = threading.Lock()
_in_flight = 0
_last_used = time.time()
_started = time.time()
_engine = None
_ref_cache = {}
_shutdown = threading.Event()


def log(msg):
    line = "[%s] %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), msg)
    # Le wrapper peut rediriger stderr vers ce même fichier : ne pas doubler les lignes.
    try:
        with open(LOG, "a", encoding="utf-8") as f:
            f.write(line)
    except OSError:
        pass
    try:
        if os.isatty(sys.stderr.fileno()):
            sys.stderr.write(line)
            sys.stderr.flush()
    except (OSError, ValueError, AttributeError):
        pass


def _bootstrap_env():
    """Rend le process autonome : espeak-ng local + jeton HF, comme le wrapper.

    Le paquet neutts embarque son propre libespeak-ng + espeak-ng-data ; les variables
    ci-dessous ne servent qu'aux installations qui utilisent un espeak-ng externe.
    """
    for base in (Path("/home/hermes/.hermes/opt/espeak-ng/usr"),
                 Path("/opt/neutts/espeak-ng/usr")):
        lib = base / "lib/x86_64-linux-gnu"
        if lib.is_dir():
            os.environ["LD_LIBRARY_PATH"] = "%s:%s" % (lib, os.environ.get("LD_LIBRARY_PATH", ""))
            os.environ["ESPEAK_DATA_PATH"] = str(lib / "espeak-ng-data")
            os.environ["PATH"] = "%s:%s" % (base / "bin", os.environ.get("PATH", ""))
            break
    os.environ.setdefault("OMP_NUM_THREADS", "4")
    os.environ["TOKENIZERS_PARALLELISM"] = "false"
    for env_file in (Path("/etc/neutts.env"), Path("/home/hermes/.hermes/neutts.env")):
        if not env_file.is_file():
            continue
        for raw in env_file.read_text(encoding="utf-8").splitlines():
            line = raw.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            key, _, val = line.partition("=")
            os.environ.setdefault(key.strip(), val.strip().strip('"').strip("'"))


def _write_wav(path, samples, sample_rate=24000):
    import numpy as np

    if not isinstance(samples, np.ndarray):
        samples = np.array(samples, dtype=np.float32)
    pcm = (np.clip(samples.flatten(), -1.0, 1.0) * 32767).astype(np.int16)
    data_size = len(pcm) * 2
    with open(path, "wb") as f:
        f.write(b"RIFF" + struct.pack("<I", 36 + data_size) + b"WAVEfmt ")
        f.write(struct.pack("<IHHIIHH", 16, 1, 1, sample_rate, sample_rate * 2, 2, 16))
        f.write(b"data" + struct.pack("<I", data_size) + pcm.tobytes())


def load_engine():
    """Charge backbone + codec (une seule fois)."""
    global _engine
    if _engine is not None:
        return _engine
    t0 = time.time()
    from neutts import NeuTTS

    log("chargement moteur %s ..." % DEFAULT_MODEL)
    _engine = NeuTTS(backbone_repo=DEFAULT_MODEL, backbone_device="cpu",
                     codec_repo=DEFAULT_CODEC, codec_device="cpu")
    log("moteur chargé en %.1f s (pic mémoire non mesuré ici)" % (time.time() - t0))
    return _engine


def _reference(voice):
    """(codes de référence, texte de référence) mis en cache par voix."""
    if voice in _ref_cache:
        return _ref_cache[voice]
    wav = REFS / ("%s.wav" % voice)
    txt = REFS / ("%s.txt" % voice)
    if not wav.is_file() or not txt.is_file():
        raise FileNotFoundError("référence voix introuvable : %s" % wav)
    codes = load_engine().encode_reference(str(wav))
    text = txt.read_text(encoding="utf-8-sig").strip()
    _ref_cache[voice] = (codes, text)
    return _ref_cache[voice]


def _prune_out_dir():
    try:
        now = time.time()
        for old in OUT_DIR.glob("*.wav"):
            if now - old.stat().st_mtime > OUT_KEEP_S:
                old.unlink()
    except OSError:
        pass


def _resolve_out(requested):
    """Chemin de sortie serveur : 'out' du client s'il est exploitable, sinon nom généré."""
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    if requested:
        try:
            cand = Path(requested)
            inside = cand.is_absolute() and OUT_DIR.resolve() in cand.resolve().parents
            usable = inside or (cand.is_absolute() and cand.parent.is_dir())
        except OSError:
            usable = False
        if usable:
            return cand
    name = "say_%d_%d_%04d.wav" % (int(time.time()), os.getpid(), int(time.time() * 997) % 10000)
    return OUT_DIR / name


def synthesize(text, out_path, voice):
    with _lock:
        engine = load_engine()
        codes, ref_text = _reference(voice)
        t0 = time.time()
        wav = engine.infer(text, codes, ref_text)
        out = Path(out_path)
        out.parent.mkdir(parents=True, exist_ok=True)
        tmp = out.with_name(out.name + ".part")
        try:
            import soundfile as sf

            sf.write(str(tmp), wav, 24000, format="WAV")
        except ImportError:
            _write_wav(str(tmp), wav, 24000)
        os.replace(str(tmp), str(out))
        return time.time() - t0, out.stat().st_size


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "neutts-serve/2.0"

    def log_message(self, fmt, *args):  # silence le log HTTP par défaut
        pass

    def _json(self, code, payload):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _authorized(self):
        if not TOKEN:
            return True
        return self.headers.get("X-Neutts-Token", "") == TOKEN

    def _deny(self):
        self._json(401, {"ok": False, "error": "jeton absent ou invalide"})

    def do_GET(self):
        route = self.path.split("?")[0]
        if route == "/health":  # volontairement sans jeton (supervision)
            return self._json(200, {"ok": True, "model": DEFAULT_MODEL,
                                    "codec": DEFAULT_CODEC, "voice": DEFAULT_VOICE,
                                    "loaded": _engine is not None,
                                    "idle_s": round(time.time() - _last_used, 1),
                                    "uptime_s": round(time.time() - _started, 1),
                                    "idle_timeout": IDLE_TIMEOUT,
                                    "in_flight": _in_flight,
                                    "out_dir": str(OUT_DIR)})
        if not self._authorized():
            return self._deny()
        if not route.startswith("/audio/"):
            return self._json(404, {"ok": False, "error": "not found"})
        name = route[len("/audio/"):]
        if not NAME_RE.match(name):
            return self._json(400, {"ok": False, "error": "nom invalide"})
        path = OUT_DIR / name
        if not path.is_file():
            return self._json(404, {"ok": False, "error": "introuvable"})
        data = path.read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", "audio/wav")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_POST(self):
        global _in_flight, _last_used
        route = self.path.split("?")[0]
        if not self._authorized():
            return self._deny()
        if route == "/release":
            with _state_lock:
                _last_used = time.time()
            self._json(200, {"ok": True, "action": "release"})
            log("release demandé -> arrêt")
            threading.Thread(target=_shutdown.set, daemon=True).start()
            return
        if route != "/say":
            return self._json(404, {"ok": False, "error": "not found"})
        try:
            length = int(self.headers.get("Content-Length") or 0)
            payload = json.loads(self.rfile.read(length) or b"{}")
            text = (payload.get("text") or "").strip()
            requested = payload.get("out") or ""
            voice = payload.get("voice") or DEFAULT_VOICE
            if not text:
                return self._json(400, {"ok": False, "error": "text est requis"})
        except (ValueError, json.JSONDecodeError) as exc:
            return self._json(400, {"ok": False, "error": "json invalide : %s" % exc})

        with _state_lock:
            _in_flight += 1
            _last_used = time.time()
        try:
            _prune_out_dir()
            out = _resolve_out(requested)
            seconds, size = synthesize(text, out, voice)
        except Exception as exc:  # noqa: BLE001
            log("erreur synthèse : %r" % exc)
            return self._json(500, {"ok": False, "error": "%s: %s" % (type(exc).__name__, exc)})
        finally:
            with _state_lock:
                _in_flight -= 1
                _last_used = time.time()
        log("say %d chars -> %s en %.1f s (%d octets)" % (len(text), out, seconds, size))
        self._json(200, {"ok": True, "seconds": round(seconds, 2), "bytes": size,
                         "out": str(out), "path": str(out), "name": out.name,
                         "chars": len(text)})


def _idle_watchdog():
    while not _shutdown.wait(5):
        if IDLE_TIMEOUT <= 0:
            continue
        with _state_lock:
            idle = time.time() - _last_used
            busy = _in_flight > 0
        if not busy and idle > IDLE_TIMEOUT:
            log("inactivité %.0f s > %.0f s -> arrêt" % (idle, IDLE_TIMEOUT))
            _shutdown.set()
            return


def main():
    _bootstrap_env()
    log("démarrage serveur neutts sur %s:%d (idle %s s, sortie %s)" % (HOST, PORT, IDLE_TIMEOUT, OUT_DIR))
    load_engine()
    httpd = ThreadingHTTPServer((HOST, PORT), Handler)
    httpd.daemon_threads = True
    threading.Thread(target=_idle_watchdog, name="idle-watchdog", daemon=True).start()
    threading.Thread(target=httpd.serve_forever, name="http", daemon=True).start()
    _shutdown.wait()
    log("arrêt du serveur")
    httpd.shutdown()
    return 0


if __name__ == "__main__":
    sys.exit(main())
EOF_SERVE

  cat > "$PREFIX/client.py" <<'EOF_CLIENT'
#!/usr/bin/env python3
"""Client du serveur TTS neutts : local (résident, réveillé si besoin) ou distant (portgpu).

Usage :
    client.py --text-file t.txt --out out.wav [--voice juliette] [--model REPO]
    client.py --status        # état du serveur (JSON)
    client.py --release       # arrêt propre du serveur

Cible : NEUTTS_URL (défaut http://127.0.0.1:8130). Si l'URL n'est pas locale, le serveur
distant écrit le WAV chez lui et le client le rapatrie par GET /audio/<name> — le chemin
de sortie du client n'est jamais interprété par un hôte distant.

Repli : si le serveur ne répond pas (ou sert un autre modèle), la synthèse passe par say.py
comme avant — aucune régression possible, seulement le cold start.
"""
import argparse
import json
import os
import subprocess
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

HERE = Path(__file__).resolve().parent
PORT = int(os.environ.get("NEUTTS_PORT", "8130"))
# Serveur TTS : local par défaut, ou distant (ex. http://10.1.33.71:8130) via NEUTTS_URL.
BASE = os.environ.get("NEUTTS_URL", "http://127.0.0.1:%d" % PORT).rstrip("/")
TOKEN = os.environ.get("NEUTTS_TOKEN", "")
START_TIMEOUT = float(os.environ.get("NEUTTS_START_TIMEOUT", "240"))
INFER_TIMEOUT = float(os.environ.get("NEUTTS_INFER_TIMEOUT", "1800"))
SERVER = HERE / "serve.py"
LOG = HERE / "serve.log"
DEFAULT_MODEL = "neuphonic/neutts-nano-french-q4-gguf"
LOCAL_HOSTS = {"127.0.0.1", "localhost", "::1", "0.0.0.0"}
REMOTE = (urllib.parse.urlsplit(BASE).hostname or "") not in LOCAL_HOSTS


def _headers(extra=None):
    head = {"Content-Type": "application/json"}
    if TOKEN:
        head["X-Neutts-Token"] = TOKEN
    if extra:
        head.update(extra)
    return head


def _post(path, payload=None, timeout=5.0):
    data = json.dumps(payload).encode("utf-8") if payload is not None else None
    req = urllib.request.Request(BASE + path, data=data, headers=_headers())
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read() or b"{}")


def _get(path, timeout=3.0):
    with urllib.request.urlopen(urllib.request.Request(BASE + path, headers=_headers()),
                                timeout=timeout) as resp:
        return json.loads(resp.read() or b"{}")


def _get_bytes(path, timeout=60.0):
    with urllib.request.urlopen(urllib.request.Request(BASE + path, headers=_headers()),
                                timeout=timeout) as resp:
        return resp.read()


def health(timeout=3.0):
    try:
        return _get("/health", timeout=timeout)
    except (urllib.error.URLError, OSError, ValueError):
        return None


def model_matches(model):
    """Le serveur tourne-t-il, et sert-il bien le modèle demandé ?"""
    info = health()
    if not info:
        return False
    return not model or info.get("model") == model


def start_server():
    with open(LOG, "ab") as log:
        subprocess.Popen([sys.executable, str(SERVER)], cwd=str(HERE),
                         stdin=subprocess.DEVNULL, stdout=log, stderr=log,
                         start_new_session=True)


def ensure_server(model):
    if model_matches(model):
        return True
    if health():
        sys.stderr.write("neutts: un serveur sert un autre modèle -> repli direct\n")
        return False
    start_server()
    t0 = time.time()
    while time.time() - t0 < START_TIMEOUT:
        if model_matches(model):
            sys.stderr.write("neutts: serveur démarré en %.0f s\n" % (time.time() - t0))
            return True
        time.sleep(2)
    sys.stderr.write("neutts: serveur indisponible après %.0f s -> repli direct\n" % START_TIMEOUT)
    return False


def fallback(text_file, out, model):
    """Ancien comportement : process neuf, cold start."""
    cmd = [sys.executable, str(HERE / "say.py"), "--text-file", str(text_file),
           "--out", str(out), "--model", model]
    return subprocess.call(cmd)


def say_remote(text, out, voice):
    """Serveur distant : synthèse chez lui, WAV rapatrié ici."""
    res = _post("/say", {"text": text, "voice": voice}, timeout=INFER_TIMEOUT)
    if not res.get("ok"):
        sys.stderr.write("neutts: erreur serveur (%s)\n" % res.get("error"))
        return False
    name = res.get("name")
    if not name:
        sys.stderr.write("neutts: serveur distant sans nom de sortie -> repli direct\n")
        return False
    data = _get_bytes("/audio/%s" % name)
    dest = Path(out)
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_name(dest.name + ".part")
    tmp.write_bytes(data)
    os.replace(str(tmp), str(dest))
    sys.stderr.write("OK: %s (%d chars, %.1f s, %.1f ko)\n"
                     % (out, res.get("chars", 0), res.get("seconds", 0.0), len(data) / 1024.0))
    return True


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--text-file")
    ap.add_argument("--out")
    ap.add_argument("--voice", default="juliette")
    ap.add_argument("--model", default=DEFAULT_MODEL)
    ap.add_argument("--status", action="store_true")
    ap.add_argument("--release", action="store_true")
    a = ap.parse_args()

    if a.status:
        print(json.dumps(health() or {"ok": False, "error": "serveur absent"}, indent=2))
        return 0
    if a.release:
        try:
            print(json.dumps(_post("/release", {})))
        except (urllib.error.URLError, OSError) as exc:
            print(json.dumps({"ok": False, "error": str(exc)}))
        return 0
    if not a.text_file or not a.out:
        ap.error("--text-file et --out sont requis")

    text = Path(a.text_file).read_text(encoding="utf-8").strip()
    if not text:
        sys.stderr.write("Error: empty text\n")
        return 1

    if REMOTE:
        if not model_matches(a.model):
            sys.stderr.write("neutts: serveur distant injoignable (%s) -> repli direct\n" % BASE)
            return fallback(a.text_file, a.out, a.model)
        try:
            if say_remote(text, a.out, a.voice):
                return 0
        except (urllib.error.URLError, OSError, ValueError) as exc:
            sys.stderr.write("neutts: échec via serveur distant (%s) -> repli direct\n" % exc)
        return fallback(a.text_file, a.out, a.model)

    if not ensure_server(a.model):
        return fallback(a.text_file, a.out, a.model)

    try:
        res = _post("/say", {"text": text, "out": str(Path(a.out).resolve()), "voice": a.voice},
                    timeout=INFER_TIMEOUT)
    except (urllib.error.URLError, OSError, ValueError) as exc:
        sys.stderr.write("neutts: échec via serveur (%s) -> repli direct\n" % exc)
        return fallback(a.text_file, a.out, a.model)
    if not res.get("ok"):
        sys.stderr.write("neutts: erreur serveur (%s) -> repli direct\n" % res.get("error"))
        return fallback(a.text_file, a.out, a.model)
    sys.stderr.write("OK: %s (%d chars, %.1f s)\n" % (a.out, res.get("chars", 0),
                                                      res.get("seconds", 0.0)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
