# ── 5. Secrets ───────────────────────────────────────────────────────────────
step "5/9  Secrets (/etc/neutts.env, mode 0640 root:$SVC_USER)"
old_token=""; old_hf=""
if [ -f "$ENVFILE" ]; then
  old_token="$(sed -n 's/^NEUTTS_TOKEN=//p' "$ENVFILE" | head -1)"
  old_hf="$(sed -n 's/^HF_TOKEN=//p' "$ENVFILE" | head -1)"
fi
TOK="${TOKEN:-$old_token}"
if [ -z "$TOK" ]; then
  if have openssl; then TOK="$(openssl rand -hex 24)"; else TOK="$(head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')"; fi
  TOKEN_GEN=1
else
  TOKEN_GEN=0
fi
HF="${HF_TOKEN:-$old_hf}"
if [ -z "$HF" ]; then
  printf "   Jeton Hugging Face (lecture seule des dépôts %s) : " "$MODEL_REPO"
  read -rs HF; printf "\n"
  [ -n "$HF" ] || die "jeton Hugging Face requis : les dépôts neuphonic/* sont soumis à acceptation (compte gratuit)"
fi
case "$HF" in *[!A-Za-z0-9_.-]*) die "jeton Hugging Face invalide (espaces ou guillemets)";; esac
case "$TOK" in *[!A-Za-z0-9_.-]*) die "jeton de service invalide (espaces ou guillemets)";; esac
printf 'X-Neutts-Token: %s\n' "$TOK" > "$HDR"; chmod 600 "$HDR"
hdr_file="$TMP/hf.header"; printf 'Authorization: Bearer %s\n' "$HF" > "$hdr_file"; chmod 600 "$hdr_file"
hf_code="$(curl -sS -o "$TMP/who.json" -w '%{http_code}' -H @"$hdr_file" https://huggingface.co/api/whoami-v2 || echo 000)"
[ "$hf_code" = "200" ] || die "jeton Hugging Face refusé (HTTP $hf_code) — vérifie le jeton sur https://huggingface.co/settings/tokens"
hf_name="$(python3 -c 'import json,sys;d=json.load(open(sys.argv[1]));print(d.get("name") or d.get("fullname") or "?")' "$TMP/who.json" 2>/dev/null || echo '?')"
ok "jeton Hugging Face valide (compte : $hf_name)"
for repo in $REPOS; do
  code="$(curl -sS -o /dev/null -w '%{http_code}' -H @"$hdr_file" "https://huggingface.co/api/models/$repo" || echo 000)"
  case "$code" in
    200) ok "accès au dépôt $repo";;
    401|403) die "accès refusé à $repo (HTTP $code) : ouvre https://huggingface.co/$repo et accepte les conditions avec le compte $hf_name";;
    *) warn "dépôt $repo : HTTP $code (vérification ignorée, le téléchargement tranchera)";;
  esac
done
umask 077
cat > "$ENVFILE" <<EOF
# /etc/neutts.env — secrets du moteur TTS neutts (généré par install-portgpu.sh v$VERSION le $(date -Is))
# Ne pas versionner, ne pas afficher. Lu par serve.py et par l'unité systemd.
HF_TOKEN=$HF
NEUTTS_TOKEN=$TOK
EOF
umask 022
chown root:"$SVC_USER" "$ENVFILE"; chmod 0640 "$ENVFILE"
ok "$ENVFILE écrit (0640 root:$SVC_USER) — valeurs jamais affichées"
unset HF hdr_file

# ── 6. Environnement Python ──────────────────────────────────────────────────
step "6/9  Environnement Python (venv, torch CPU, llama.cpp, neutts) — long"
VPY="$PREFIX/venv/bin/python"
if [ -x "$VPY" ] && "$VPY" -m pip --version >/dev/null 2>&1; then ok "venv existant réutilisé : $PREFIX/venv"
else
  python3 -m venv "$PREFIX/venv"
  "$VPY" -m pip install --upgrade pip wheel setuptools >/dev/null
  ok "venv créé ($("$VPY" -V 2>&1))"
fi
if [ "$DEPS_FORCE" != "1" ] && "$VPY" - <<'PY' 2>/dev/null
import importlib.metadata as m
for p in ("torch","torchaudio","llama-cpp-python","neutts"): m.version(p)
PY
then
  ok "dépendances Python déjà installées (DEPS_FORCE=1 pour réinstaller)"
else
  export HF_HOME="$STATE/hf" PIP_DISABLE_PIP_VERSION_CHECK=1
  printf "   torch/torchaudio (roues CPU officielles)…\n"
  if ! "$VPY" -m pip install --index-url https://download.pytorch.org/whl/cpu \
        --extra-index-url https://pypi.org/simple "torch==2.14.1+cpu" "torchaudio==2.11.0+cpu"; then
    warn "versions épinglées indisponibles pour ce Python — installation non épinglée"
    "$VPY" -m pip install --index-url https://download.pytorch.org/whl/cpu \
        --extra-index-url https://pypi.org/simple torch torchaudio
  fi
  printf "   llama-cpp-python (roue précompilée, variante %s)…\n" "$LLAMA_VARIANT"
  if ! "$VPY" -m pip install --only-binary=llama-cpp-python --extra-index-url "$LLAMA_IDX" \
        "llama-cpp-python==0.3.36"; then
    warn "pas de roue précompilée : compilation depuis les sources (10 à 20 minutes, cmake/gcc requis)"
    DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends build-essential cmake ninja-build python3-dev
    case "$LLAMA_VARIANT" in
      cpu) CMAKE_FLAGS="-DGGML_NATIVE=ON";;
      *) have nvcc || die "variante $LLAMA_VARIANT demandée mais nvcc absent (installe le toolkit CUDA)"
         CMAKE_FLAGS="-DGGML_CUDA=ON";;
    esac
    CMAKE_ARGS="$CMAKE_FLAGS" "$VPY" -m pip install --no-cache-dir "llama-cpp-python==0.3.36"
  fi
  printf "   neutts (paquet + dépendances)…\n"
  "$VPY" -m pip install "neutts[llama]==1.4.1"
  unset HF_HOME
fi
"$VPY" -c 'import importlib.metadata as m;print("   versions : " + " | ".join("%s %s" % (p, m.version(p)) for p in ("torch","torchaudio","llama-cpp-python","neutts","transformers")))'
"$VPY" -m pip freeze > "$PREFIX/freeze.txt" 2>/dev/null || true
chmod 0644 "$PREFIX/freeze.txt"; ok "empreinte des versions : $PREFIX/freeze.txt"

# ── 7. Unité systemd ─────────────────────────────────────────────────────────
step "7/9  Unité systemd « neutts » (moteur permanent)"
cat > "$UNIT" <<EOF
[Unit]
Description=Moteur TTS NeuTTS resident (portgpu)
Documentation=file:$PREFIX/serve.py
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=$SVC_USER
Group=$SVC_USER
WorkingDirectory=$PREFIX
EnvironmentFile=$ENVFILE
Environment=NEUTTS_HOST=$BIND
Environment=NEUTTS_PORT=$PORT
Environment=NEUTTS_IDLE_TIMEOUT=$IDLE
Environment=NEUTTS_REFS=$PREFIX/refs
Environment=NEUTTS_OUT_DIR=$STATE/out
Environment=NEUTTS_LOG=$STATE/serve.log
Environment=NEUTTS_MODEL=$MODEL_REPO
Environment=NEUTTS_CODEC=$CODEC_REPO
Environment=HF_HOME=$STATE/hf
Environment=OMP_NUM_THREADS=$THREADS
Environment=TOKENIZERS_PARALLELISM=false
Environment=PYTHONUNBUFFERED=1
ExecStart=$PREFIX/venv/bin/python $PREFIX/serve.py
Restart=always
RestartSec=3
TimeoutStopSec=25
KillSignal=SIGTERM
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=read-only
ReadWritePaths=$STATE
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
LockPersonality=true
MemoryMax=80%
StandardOutput=append:$STATE/serve.log
StandardError=append:$STATE/serve.log

[Install]
WantedBy=multi-user.target
EOF
chmod 0644 "$UNIT"
systemctl daemon-reload
systemctl enable neutts >/dev/null
ok "$UNIT activé au démarrage"

# ── 8. Pare-feu ──────────────────────────────────────────────────────────────
step "8/9  Pare-feu (source $ALLOW_CIDR uniquement)"
if [ "$BIND" = "127.0.0.1" ]; then ok "écoute locale seulement : aucune règle ouverte"
elif have ufw && ufw status 2>/dev/null | grep -q '^Status: active'; then
  ufw allow from "$ALLOW_CIDR" to any port "$PORT" proto tcp comment 'neutts TTS' >/dev/null && ok "ufw : $ALLOW_CIDR -> $PORT/tcp"
elif have firewall-cmd && firewall-cmd --state >/dev/null 2>&1; then
  firewall-cmd --permanent --add-rich-rule="rule family=ipv4 source address=$ALLOW_CIDR port port=$PORT protocol=tcp accept" >/dev/null
  firewall-cmd --reload >/dev/null && ok "firewalld : $ALLOW_CIDR -> $PORT/tcp"
else
  warn "aucun pare-feu local actif (ufw/firewalld) : le filtrage dépend de l'amont réseau"
fi

# ── 9. Recette ───────────────────────────────────────────────────────────────
step "9/9  Démarrage et recette (le 1er démarrage télécharge ~3,5 Go de modèles)"
systemctl restart neutts
health() { curl -fsS --max-time 5 "http://127.0.0.1:$PORT/health" 2>/dev/null || true; }
loaded() { health | python3 -c 'import json,sys;print(json.load(sys.stdin).get("loaded"))' 2>/dev/null || echo False; }
t0=$(date +%s); loaded_ok=0
while :; do
  [ "$(loaded)" = "True" ] && { loaded_ok=1; break; }
  if ! systemctl is-active --quiet neutts; then
    printf "\n"; journalctl -u neutts -n 25 --no-pager || true
    die "le service s'est arrêté — journal ci-dessus"
  fi
  el=$(( $(date +%s) - t0 ))
  [ "$el" -gt 2400 ] && { printf "\n"; die "chargement non terminé après 40 min — journalctl -u neutts"; }
  if [ $(( el % 15 )) -lt 5 ]; then printf "\r   chargement… %3d s" "$el"; fi
  sleep 5
done
printf "\n   modèle chargé en %d s\n" "$(( $(date +%s) - t0 ))"
ok "service actif : $(systemctl is-active neutts) / activé au boot : $(systemctl is-enabled neutts)"
printf '   /health : %s\n' "$(health)"
say() {  # $1 = texte ; réponse JSON sur stdout
  python3 -c 'import json,sys;json.dump({"text":sys.argv[1]},open(sys.argv[2],"w"))' "$1" "$BODY"
  curl -fsS --max-time 300 -H @"$HDR" -H 'Content-Type: application/json' -d @"$BODY" \
    "http://127.0.0.1:$PORT/say"
}
ph1="Test du moteur vocal resident sur portgpu, premiere phrase de controle."
ph2="Deuxieme phrase, un peu plus longue, pour verifier la fidelite et la duree de la synthese vocale."
for i in 1 2; do
  eval "txt=\$ph$i"
  s=$(date +%s%N); out="$(say "$txt")"; e=$(date +%s%N)
  printf '%s\n' "$out" | python3 -c 'import json,sys;d=json.load(sys.stdin);print("   synthèse %s : %.2f s moteur, %.2f s total, %d octets -> %s" % (sys.argv[1], d["seconds"], (int(sys.argv[2])-int(sys.argv[3]))/1e9, d["bytes"], d["out"]))' "$i" "$e" "$s"
  wav="$(printf '%s\n' "$out" | python3 -c 'import json,sys;print(json.load(sys.stdin)["path"])')"
  "$PREFIX/venv/bin/python" - "$wav" <<'PY'
import soundfile as sf, sys
info = sf.info(sys.argv[1])
print("   WAV vérifié : %d trames, %d Hz, %.1f s" % (info.frames, info.samplerate, info.duration))
PY
done
[ "$(loaded)" = "True" ] || die "le moteur s'est déchargé pendant la recette"
ok "recette OK : moteur résident, synthèses produites et WAV relus"

